        eng.saveQueue();
        if (!item) {
            eng.current = null;
            eng.emit();
            if (cfg.autoRequest !== false) {
                eng.request('', function(ok) {
                    if (!ok && !eng.queue.length) eng.loopFromHistory();
                });
                return;
